        if (before->regs[i] != after->regs[i]) {
            if (!any) {
                fprintf(stderr, "  regdiff 0x%08x:", encoding);
                any = true;
            }
            fprintf(stderr, " r%d=0x%lx->0x%lx",
                    i,
                    (unsigned long)before->regs[i],
                    (unsigned long)after->regs[i]);
        }
