    if (before->cp0_epc + 4 != after->cp0_epc) {
        if (!any) {
            fprintf(stderr, "  regdiff 0x%08x:", encoding);
            any = true;
        }
        fprintf(stderr, " pc=0x%lx->0x%lx",
                (unsigned long)before->cp0_epc,
                (unsigned long)after->cp0_epc);
    }
    if (any)
        fprintf(stderr, "\\n");
